import{_ as r,a0 as a,w as u,s as l,ao as p,I as o,x as s,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 中檢查你的 IP 地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中檢查你的 IP 地址 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中檢查你的 IP 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中檢查你的 IP 地址 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190823 How To Check Your IP Address in Ubuntu -Beginner-s Tip","title":"如何在 Ubuntu 中檢查你的 IP 地址","tag":"201909","desc":""},"relativePath":"201909/20190823 How To Check Your IP Address in Ubuntu -Beginner-s Tip.md","filePath":"[post].md"}'),d={name:"201909/20190823 How To Check Your IP Address in Ubuntu -Beginner-s Tip.md"};function g(b,t,h,f,m,P){const n=a("Link");return u(),l("div",null,[t[23]||(t[23]=p('<h1 id="如何在-ubuntu-中檢查你的-ip-地址" tabindex="-1">如何在 Ubuntu 中檢查你的 IP 地址 <a class="header-anchor" href="#如何在-ubuntu-中檢查你的-ip-地址" aria-label="Permalink to “如何在 Ubuntu 中檢查你的 IP 地址”">​</a></h1><p>不知道你的 IP 地址是什麼？以下是在 Ubuntu 和其他 Linux 發行版中檢查 IP 地址的幾種方法。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/checking-ip-address-ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="什麼是-ip-地址" tabindex="-1">什麼是 IP 地址？ <a class="header-anchor" href="#什麼是-ip-地址" aria-label="Permalink to “什麼是 IP 地址？”">​</a></h3><p><strong>互聯網協議地址</strong>（通常稱為 <strong>IP 地址</strong>）是分配給連接到計算機網絡的每個設備（使用互聯網協議）的數字標籤。IP 地址用於識別和定位機器。</p><p><strong>IP 地址</strong>在網絡中是<em>唯一的</em>，使得所有連接設備能夠通信。</p><p>你還應該知道有兩種<strong>類型的 IP 地址</strong>：<strong>公有</strong>和<strong>私有</strong>。<strong>公有 IP 地址</strong>是用於互聯網通信的地址，這與你用於郵件的物理地址相同。但是，在本地網絡（例如使用路由器的家庭）的環境中，會為每個設備分配在該子網內唯一的<strong>私有 IP 地址</strong>。這在本地網絡中使用，而不直接暴露公有 IP（路由器用它與互聯網通信）。</p><p>另外還有區分 <strong>IPv4</strong> 和 <strong>IPv6</strong> 協議。<strong>IPv4</strong> 是經典的 IP 格式，它由基本的 4 部分結構組成，四個字節用點分隔（例如 127.0.0.1）。但是，隨着設備數量的增加，IPv4 很快就無法提供足夠的地址。這就是 <strong>IPv6</strong> 被髮明的原因，它使用 <strong>128 位地址</strong>的格式（與 <strong>IPv4</strong> 使用的 <strong>32 位地址</strong>相比）。</p><h3 id="在-ubuntu-中檢查你的-ip-地址-終端方式" tabindex="-1">在 Ubuntu 中檢查你的 IP 地址（終端方式） <a class="header-anchor" href="#在-ubuntu-中檢查你的-ip-地址-終端方式" aria-label="Permalink to “在 Ubuntu 中檢查你的 IP 地址（終端方式）”">​</a></h3><p>檢查 IP 地址的最快和最簡單的方法是使用 <code>ip</code> 命令。你可以按以下方式使用此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip addr show</span></span></code></pre></div><p>它將同時顯示 IPv4 和 IPv6 地址：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/ip_addr_show.png?fit=800%2C493&amp;ssl=1" alt="Display IP Address in Ubuntu Linux"></p><p>實際上，你可以進一步縮短這個命令 <code>ip a</code>。它會給你完全相同的結果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip a</span></span></code></pre></div><p>如果你希望獲得最少的細節，也可以使用 <code>hostname</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hostname -I</span></span></code></pre></div>',17)),o("p",null,[t[1]||(t[1]=s("還有一些",-1)),i(n,{href:"https://linuxhandbook.com/find-ip-address/"},{default:e(()=>[...t[0]||(t[0]=[s("在 Linux 中檢查 IP 地址的方法",-1)])]),_:1}),t[2]||(t[2]=s("，但是這兩個命令足以滿足這個目的。",-1))]),t[24]||(t[24]=p('<p><code>ifconfig</code> 如何？</p><p>老用户可能會想要使用 <code>ifconfig</code>（net-tools 軟件包的一部分），但該程序已被棄用。一些較新的 Linux 發行版不再包含此軟件包，如果你嘗試運行它，你將看到 ifconfig 命令未找到的錯誤。</p><h3 id="在-ubuntu-中檢查你的-ip-地址-gui-方式" tabindex="-1">在 Ubuntu 中檢查你的 IP 地址（GUI 方式） <a class="header-anchor" href="#在-ubuntu-中檢查你的-ip-地址-gui-方式" aria-label="Permalink to “在 Ubuntu 中檢查你的 IP 地址（GUI 方式）”">​</a></h3><p>如果你對命令列不熟悉，你還可以使用圖形方式檢查 IP 地址。</p><p>打開 Ubuntu 應用菜單（在屏幕左下角<strong>顯示應用</strong>）並搜索<strong>Settings</strong>，然後單擊圖標：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/08/applications_menu_settings.jpg?fit=800%2C309&amp;ssl=1" alt="Applications Menu Settings"></p><p>這應該會打開<strong>設置菜單</strong>。進入<strong>網絡</strong>：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/network_settings_ubuntu.jpg?fit=800%2C591&amp;ssl=1" alt="Network Settings Ubuntu"></p><p>按下連接旁邊的<strong>齒輪圖標</strong>會打開一個窗口，其中包含更多設置和有關你網絡鏈接的信息，其中包括你的 IP 地址：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/ip_address_gui_ubuntu.png?fit=800%2C510&amp;ssl=1" alt="IP Address GUI Ubuntu"></p><h3 id="額外提示-檢查你的公共-ip-地址-適用於台式計算機" tabindex="-1">額外提示：檢查你的公共 IP 地址（適用於台式計算機） <a class="header-anchor" href="#額外提示-檢查你的公共-ip-地址-適用於台式計算機" aria-label="Permalink to “額外提示：檢查你的公共 IP 地址（適用於台式計算機）”">​</a></h3>',11)),o("p",null,[t[4]||(t[4]=s("首先，要檢查你的",-1)),t[5]||(t[5]=o("strong",null,"公有 IP 地址",-1)),t[6]||(t[6]=s("（用於與服務器通信），你可以",-1)),i(n,{href:"https://linuxhandbook.com/curl-command-examples/"},{default:e(()=>[...t[3]||(t[3]=[s("使用 curl 命令",-1)])]),_:1}),t[7]||(t[7]=s("。打開終端並輸入以下命令：",-1))]),t[25]||(t[25]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl ifconfig.me</span></span></code></pre></div><p>這應該只會返回你的 IP 地址而沒有其他多餘信息。我建議在分享這個地址時要小心，因為這相當於公佈你的個人地址。</p><p><strong>注意：</strong> 如果 <code>curl</code> 沒有安裝，只需使用 <code>sudo apt install curl -y</code> 來解決問題，然後再試一次。</p><p>另一種可以查看公共 IP 地址的簡單方法是在 Google 中搜索 “ip address”。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本文中，我介紹了在 Uuntu Linux 中找到 IP 地址的不同方法，並向你概述了 IP 地址的用途以及它們對我們如此重要的原因。</p><p>我希望你喜歡這篇文章。如果你覺得文章有用，請在評論欄告訴我們！</p><hr>',8)),o("p",null,[t[9]||(t[9]=s("via: ",-1)),i(n,{href:"https://itsfoss.com/check-ip-address-ubuntu/"},{default:e(()=>[...t[8]||(t[8]=[s("https://itsfoss.com/check-ip-address-ubuntu/",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=s("作者：",-1)),i(n,{href:"https://itsfoss.com/author/sergiu/"},{default:e(()=>[...t[10]||(t[10]=[s("Sergiu",-1)])]),_:1}),t[15]||(t[15]=s(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[11]||(t[11]=[s("lujun9972",-1)])]),_:1}),t[16]||(t[16]=s(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[12]||(t[12]=[s("geekpi",-1)])]),_:1}),t[17]||(t[17]=s(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[20]||(t[20]=s("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[18]||(t[18]=[s("LCTT",-1)])]),_:1}),t[21]||(t[21]=s(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...t[19]||(t[19]=[s("Linux中國",-1)])]),_:1}),t[22]||(t[22]=s(" 榮譽推出",-1))])])}const C=r(d,[["render",g]]);export{T as __pageData,C as default};
